import{_ as o,o as a,c as t,a3 as d}from"./chunks/framework.CVt6dz2a.js";const m=JSON.parse('{"title":"EP.32 着色器写成函数之后","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.32-shader-as-function.md","filePath":"comics/EP.32-shader-as-function.md","lastUpdated":1793881879000}'),r={name:"comics/EP.32-shader-as-function.md"};function l(c,e,i,s,n,u){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="ep-32-着色器写成函数之后" tabindex="-1">EP.32 着色器写成函数之后 <a class="header-anchor" href="#ep-32-着色器写成函数之后" aria-label="Permalink to &quot;EP.32 着色器写成函数之后&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/32-tsl-compute/basics">32.1 基础入门：TSL 节点与函数式着色器</a> 延伸阅读：<a href="./../guide/32-tsl-compute/advanced">32.2 进阶应用：Compute Shader 与 GPU 数据流</a> · <a href="./../guide/32-tsl-compute/practice">32.3 实战案例：GPU 驱动的可交互粒子场</a> 动手演示：<a href="./../public/demos/tsl-compute/tsl-node-lab.html">tsl-node-lab TSL 节点实验室</a> · <a href="./../public/demos/tsl-compute/compute-particles-lab.html">compute-particles-lab Compute 粒子实验室</a> · <a href="./../public/demos/tsl-compute/gpu-field-lab.html">gpu-field-lab GPU 可交互粒子场</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱把一段 GLSL 抄成顶点与片元两份字符串，改了一处忘了另一处，球体上的条纹突然消失；标签君在旁边看着两段代码，完全对不上号。</td></tr><tr><td>② 揭秘</td><td>码叔把同一套公式拆成节点：<code>uv()</code> → <code>sin()</code> → <code>mix()</code> → <code>colorNode</code>；着色器不再是一段文本，而是一棵可以复用、可以编译到不同后端的函数图。</td></tr><tr><td>③ 实证</td><td>同一个球体，TSL 节点版与 GLSL 字符串版并排对照；条纹数量、菲涅尔边缘、噪声流向都对得上，差异只在光照近似。</td></tr><tr><td>④ 结案</td><td>三条上手纪律：节点必须挂到材质、颜色用 <code>color()</code>、uniform 更新改 <code>.value</code>；最后补一句——战略前瞻，了解即可，按需采用。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-字符串的痛-改一处-漏一处" tabindex="-1">① 字符串的痛：改一处，漏一处 <a class="header-anchor" href="#_1-字符串的痛-改一处-漏一处" aria-label="Permalink to &quot;① 字符串的痛：改一处，漏一处&quot;">​</a></h3><p>GLSL 的经典写法是把顶点着色器与片元着色器写成两段字符串，再用 <code>varying</code> 把数据从前者传到后者。问题不在于 GLSL 本身，而在于&quot;两份文本&quot;这种组织方式：变量名要手工对齐，类型要手工对齐，改结构时要同时改两处。<strong>只要有一处漏改，编译可能仍然通过，画面却会悄悄坏掉</strong>——条纹消失、颜色变黑、边缘光不见，都是常见的&quot;静默失败&quot;。</p><h3 id="_2-节点图-把着色器变成函数调用" tabindex="-1">② 节点图：把着色器变成函数调用 <a class="header-anchor" href="#_2-节点图-把着色器变成函数调用" aria-label="Permalink to &quot;② 节点图：把着色器变成函数调用&quot;">​</a></h3><p>TSL 的做法是把每个运算都变成一个节点：<code>uv()</code> 返回 UV 节点，<code>sin()</code> 返回正弦节点，<code>mix()</code> 把两个节点组合成插值节点。节点之间用方法链串起来，形成一张有向无环图。材质的 <code>colorNode</code>、<code>emissiveNode</code> 只是这张图的挂载点。<strong>节点图在编译期固化成着色器，运行时只更新 uniform</strong>，所以它既有函数组合的灵活，又没有逐帧解释的开销。</p><p>同一张图可以编译到 WGSL（WebGPU）或 GLSL（WebGL2）。这就是&quot;统一后端&quot;：你不需要维护两套源码，只需要接受两个后端在精度与光照上的细微差异。</p><h3 id="_3-对照-图案一致-光照近似" tabindex="-1">③ 对照：图案一致，光照近似 <a class="header-anchor" href="#_3-对照-图案一致-光照近似" aria-label="Permalink to &quot;③ 对照：图案一致，光照近似&quot;">​</a></h3><p>演示里的 TSL 版与 GLSL 版使用同一套条纹、菲涅尔、噪声公式。TSL 版走 <code>MeshStandardNodeMaterial</code> 的标准光照，GLSL 版用固定方向光近似，所以两边的亮度与高光会略有不同。<strong>判断一致性要看结构：条纹数量、渐变方向、边缘光宽度、噪声流向是否对齐</strong>，而不是逐像素亮度相同。这也是迁移旧着色器时最实用的验收方法。</p><h3 id="_4-三条纪律与一句定位" tabindex="-1">④ 三条纪律与一句定位 <a class="header-anchor" href="#_4-三条纪律与一句定位" aria-label="Permalink to &quot;④ 三条纪律与一句定位&quot;">​</a></h3><ul><li>节点必须挂到材质通道，光声明不赋值不会生效；</li><li>颜色常量用 <code>color(0x...)</code>，不要手工写线性 RGB；</li><li>uniform 更新改 <code>.value</code>，不要重新给节点变量赋值；</li><li>TSL 是战略前瞻内容，当前阶段了解即可，按需采用。</li></ul><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：<code>colorNode</code> 赋了值，画面完全没变？</strong> 检查材质是不是 <code>NodeMaterial</code>、渲染器是不是 <code>WebGPURenderer</code>，以及赋值后是否需要 <code>needsUpdate</code>。</li><li><strong>Q：颜色比 GLSL 版亮/灰？</strong> 多半是色彩空间不一致。<code>color()</code> 会做 sRGB 到线性的转换，手写 <code>vec3</code> 不会。</li><li><strong>Q：每帧改 uniform 却不生效？</strong> 改的是 JS 变量，不是节点的 <code>.value</code>。材质引用的是旧节点。</li><li><strong>Q：没有 WebGPU 还能用吗？</strong> 能。<code>WebGPURenderer</code> 会回退到 WebGL2，节点材质仍然可用，只是 compute 等能力受限。</li><li><strong>Q：什么时候不该用 TSL？</strong> 目标环境以 WebGL2 为主、团队不熟节点体系、效果简单到 GLSL 字符串足够时，迁移收益有限。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>TSL 的节点图在什么时候被编译成着色器？运行时改变的到底是什么？</li><li>为什么 TSL 版和 GLSL 版的图案能对齐，但亮度不一定相同？</li><li>说出三条从 GLSL 迁移到 TSL 时最容易踩的坑，并给出对应的检查方法。</li></ol><details><summary>答案</summary><ol><li>节点图在材质首次编译时固化成着色器；运行时只更新 uniform 的值，节点结构不变。因此变化的部分应交给 uniform，不变的部分才固化成节点。</li><li>因为两版共用同一套条纹、菲涅尔、噪声公式，结构一致；但 TSL 版走标准 PBR 光照，GLSL 版用固定方向光近似，光照模型不同，亮度与高光自然有差异。验收时应比较图案结构而不是逐像素亮度。</li><li>① 节点没挂到材质：检查 <code>material.colorNode</code> 等插槽是否真正赋值；② 颜色空间不一致：统一用 <code>color()</code>，并核对 <code>outputColorSpace</code>；③ uniform 更新方式错误：改 <code>node.value</code> 而不是重新赋值变量。补充一条：WebGL2 回退不支持 compute，涉及 GPU 计算时要准备降级路径。</li></ol></details>',19)])])}const p=o(r,[["render",l]]);export{m as __pageData,p as default};
